output_text:
[
  {
    "id": "must_take_cart_from_bay",
    "text": "Customers are obliged to check out a shopping cart from the cart bay before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "cart_bay": "at(1,5)",
        "with_cart": "hasCart"
      },
      "events": {
        "take_cart_from_bay": {
          "pre": {
            "and": [
              "cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "with_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_cart_from_bay"
    }
  },
  {
    "id": "items_must_go_in_cart",
    "text": "Customers are prohibited from picking up required items by hand instead of putting them into a cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "carrying_by_hand": "handFull"
      },
      "events": {
        "hand_pickup": {
          "pre": {
            "and": [
              {
                "not": "with_cart"
              },
              "PICKUP_ITEM"
            ]
          },
          "post": "carrying_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "hand_pickup"
        ]
      }
    }
  },
  {
    "id": "return_cart_to_front_corral",
    "text": "Before leaving the store, customers are obliged to park the cart at the front-left cart return area.",
    "abstraction": {
      "state_properties": {
        "front_cart_return": "at(0,1)",
        "cart_parked_at_front_return": "cartAt(0,1)"
      },
      "events": {
        "return_cart_to_front_corral": {
          "pre": {
            "and": [
              "front_cart_return",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_front_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_front_corral"
    }
  },
  {
    "id": "no_abandoning_cart_elsewhere",
    "text": "Customers are prohibited from leaving a cart anywhere except the designated front-left cart return area.",
    "abstraction": {
      "state_properties": {
        "front_cart_return": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_corral": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "front_cart_return"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_corral"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Customers are prohibited from taking a shopping cart through the exit.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart"
      },
      "events": {
        "exit_while_pushing_cart": {
          "pre": {
            "and": [
              "with_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_while_pushing_cart"
    }
  },
  {
    "id": "eggs_cart_must_turn_back",
    "text": "After collecting an item from the eggs shelf while pushing a cart, customers are obliged to turn back west rather than continue deeper into that aisle.",
    "abstraction": {
      "state_properties": {
        "eggs_pickup_position": "at(6,4)",
        "with_cart": "hasCart"
      },
      "events": {
        "collect_eggs_with_cart": {
          "pre": {
            "and": [
              "eggs_pickup_position",
              "with_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": "with_cart"
        },
        "turn_west_from_eggs_with_cart": {
          "pre": {
            "and": [
              "eggs_pickup_position",
              "with_cart",
              "W"
            ]
          },
          "post": "with_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "collect_eggs_with_cart",
      "discharge": "turn_west_from_eggs_with_cart"
    }
  },
  {
    "id": "no_cart_east_from_2_5",
    "text": "The lower exit corridor may be entered eastbound from cell (2,5) only on foot, not while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "lower_corridor_gate": "at(2,5)",
        "with_cart": "hasCart",
        "on_foot": {
          "not": "hasCart"
        }
      },
      "events": {
        "push_cart_east_into_lower_corridor": {
          "pre": {
            "and": [
              "lower_corridor_gate",
              "with_cart",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "push_cart_east_into_lower_corridor"
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "Once the cart has been returned to the front corral, customers are prohibited from doing any further shopping interactions before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)"
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_returned",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
